use std::{env, error::Error, fs, io, path::PathBuf};

use ga_domain::model_response::{ModelResponseError, StructuredProvider, StructuredResponseSchema};
use serde_json::{Value, json};

#[test]
#[ignore = "requires the synthetic provider responses generated by pinned Python"]
fn matches_pinned_provider_output_decisions() -> Result<(), Box<dyn Error>> {
    let root = PathBuf::from(env::var("GA_TEST_MODEL_RESPONSES")?);
    let reference: Value = serde_json::from_slice(&fs::read(root.join("manifest.json"))?)?;
    let schemas = &reference["schemas"];
    let openai = StructuredResponseSchema::new(&schemas["openai"], &schemas["application"])?;
    let anthropic = StructuredResponseSchema::new(&schemas["anthropic"], &schemas["application"])?;
    let cases = reference["cases"]
        .as_array()
        .ok_or("Expected fixture cases")?;
    for (index, case) in cases.iter().enumerate() {
        let (provider, schema) = match case["provider"].as_str() {
            Some("openai") => (StructuredProvider::OpenAi, &openai),
            Some("anthropic") => (StructuredProvider::Anthropic, &anthropic),
            _ => return Err(io::Error::other("Unknown fixture provider").into()),
        };
        let body = fs::read(root.join(format!("case-{index}.json")))?;
        let result = match schema.decode(provider, &body) {
            Ok(output) => json!({
                "value": output.value,
                "usage": output.usage.map(|usage| json!({
                    "input_tokens": usage.input_tokens,
                    "output_tokens": usage.output_tokens,
                })),
            }),
            Err(error) => {
                assert!(!error.to_string().contains("synthetic-provider-private"));
                let label = match error {
                    ModelResponseError::Refused => "ProviderRefused",
                    ModelResponseError::Incomplete => "ProviderOutputTruncated",
                    ModelResponseError::Unavailable => "ProviderUnavailable",
                    ModelResponseError::InvalidSchema => "UnexpectedSchemaError",
                    ModelResponseError::TooLarge
                    | ModelResponseError::InvalidEnvelope
                    | ModelResponseError::InvalidOutput => "ProviderOutputInvalid",
                };
                json!({"error": label})
            }
        };
        assert_eq!(result, case["expected"], "provider fixture case {index}");
    }
    Ok(())
}
